import { FIRSTS, CATEGORY_META } from "./dashboardData";

const STAGE_COUNTS = {
  one: FIRSTS.filter((f) => f.stage === "one").length,
  two: FIRSTS.filter((f) => f.stage === "two").length,
  three: FIRSTS.filter((f) => f.stage === "three").length,
  four: FIRSTS.filter((f) => f.stage === "four").length,
};

const TOTAL_COUNT =
  STAGE_COUNTS.one + STAGE_COUNTS.two + STAGE_COUNTS.three + STAGE_COUNTS.four;

export type CohortStudent = {
  id: number;
  name: string;
  email: string;
  stagePct: { one: number; two: number; three: number; four: number };
  daysInactive: number;
  sharedCount: number;
};

export type Cohort = {
  id: string;
  name: string;
  focus: string;
  institution: string;
  students: CohortStudent[];
  /** Average completion, sampled roughly weekly over the last 8 weeks, for trend charts. */
  weeklyTrend: number[];
};

export function studentOverallPct(s: CohortStudent): number {
  const weighted =
    STAGE_COUNTS.one * s.stagePct.one +
    STAGE_COUNTS.two * s.stagePct.two +
    STAGE_COUNTS.three * s.stagePct.three +
    STAGE_COUNTS.four * s.stagePct.four;
  return Math.round(weighted / TOTAL_COUNT);
}

const STAGE_ORDER: (keyof CohortStudent["stagePct"])[] = ["one", "two", "three", "four"];
const STAGE_SHORT_LABEL: Record<keyof CohortStudent["stagePct"], string> = {
  one: "Stage One",
  two: "Stage Two",
  three: "Stage Three",
  four: "Stage Four",
};

/** The stage a student is currently working through: the earliest stage that isn't yet 100%. "complete" if all four are. */
export function studentCurrentStage(s: CohortStudent): keyof CohortStudent["stagePct"] | "complete" {
  for (const stage of STAGE_ORDER) {
    if (s.stagePct[stage] < 100) return stage;
  }
  return "complete";
}

export type StageDistributionBucket = {
  key: string;
  label: string;
  count: number;
};

/** How many students are currently sitting in each stage, right now, plus a "complete" bucket. */
export function stageDistribution(students: CohortStudent[]): StageDistributionBucket[] {
  const buckets: StageDistributionBucket[] = [
    ...STAGE_ORDER.map((s) => ({ key: s, label: STAGE_SHORT_LABEL[s], count: 0 })),
    { key: "complete", label: "Complete", count: 0 },
  ];
  for (const s of students) {
    const stage = studentCurrentStage(s);
    const bucket = buckets.find((b) => b.key === stage)!;
    bucket.count += 1;
  }
  return buckets;
}

const CATEGORY_STAGE: Record<string, keyof CohortStudent["stagePct"]> = {
  A: "one", B: "one", C: "one", D: "one",
  E: "two", F: "two", G: "two", H: "two", I: "two", J: "two",
  K: "three", L: "three", M: "three",
  N: "four", O: "four",
};

function hashSeed(seed: string): number {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

/**
 * A student's stage percentage doesn't break down by category, so each
 * student's category standing is derived from their stage percentage plus a
 * deterministic per-(student, category) offset, seeded so it's stable across
 * reloads. Averaged across a whole cohort this still surfaces a believable,
 * consistent weak-spot signal without needing category-level tracking per
 * student.
 */
function categoryPctForStudent(s: CohortStudent, category: string): number {
  const stage = CATEGORY_STAGE[category];
  const base = s.stagePct[stage];
  if (base === 0) return 0;
  const jitter = ((hashSeed(`${s.id}|${category}`) % 29) - 14);
  return Math.max(0, Math.min(100, base + jitter));
}

export type CategoryWeakSpotRow = {
  stage: keyof CohortStudent["stagePct"];
  shortLabel: string;
  categories: { category: string; label: string; color: string; pct: number }[];
};

/** Cohort-average completion per category, grouped by stage, same shape as the student-facing category heatmap but averaged across every student. */
export function categoryWeakSpot(students: CohortStudent[]): CategoryWeakSpotRow[] {
  return STAGE_ORDER.map((stage) => {
    const categories = (Object.keys(CATEGORY_STAGE) as (keyof typeof CATEGORY_META)[])
      .filter((cat) => CATEGORY_STAGE[cat] === stage)
      .map((cat) => {
        const avg = students.length
          ? Math.round(students.reduce((sum, s) => sum + categoryPctForStudent(s, cat), 0) / students.length)
          : 0;
        return { category: cat, label: CATEGORY_META[cat].label, color: CATEGORY_META[cat].color, pct: avg };
      });
    return { stage, shortLabel: STAGE_SHORT_LABEL[stage], categories };
  });
}

/** The single weakest category across the whole cohort, for a callout. */
export function weakestCategory(rows: CategoryWeakSpotRow[]): { label: string; pct: number } | null {
  const all = rows.flatMap((r) => r.categories);
  if (all.length === 0) return null;
  return all.reduce((min, c) => (c.pct < min.pct ? c : min), all[0]);
}

export type StalledReason = "inactive" | "stalled-mid-stage" | "both";

export type StalledStudent = CohortStudent & {
  cohortId: string;
  cohortName: string;
  currentStage: keyof CohortStudent["stagePct"] | "complete";
  currentStagePct: number;
  reason: StalledReason;
  reasonLabel: string;
  riskScore: number;
};

const INACTIVE_THRESHOLD_DAYS = 14;
const STALLED_MID_STAGE_THRESHOLD_DAYS = 5;

/**
 * Students inactive 14+ days, or who clearly began their current stage
 * (non-zero progress in it) but haven't touched it in 5+ days. Ranked by
 * days inactive, the plainest, most explainable risk signal available.
 */
export function stalledStudents(cohorts: Cohort[]): StalledStudent[] {
  const flagged: StalledStudent[] = [];

  for (const cohort of cohorts) {
    for (const s of cohort.students) {
      const currentStage = studentCurrentStage(s);
      const currentStagePct = currentStage === "complete" ? 100 : s.stagePct[currentStage];

      const inactive = s.daysInactive >= INACTIVE_THRESHOLD_DAYS;
      const stalledMidStage =
        currentStage !== "complete" &&
        currentStagePct > 0 &&
        currentStagePct < 100 &&
        s.daysInactive >= STALLED_MID_STAGE_THRESHOLD_DAYS;

      if (!inactive && !stalledMidStage) continue;

      const reason: StalledReason = inactive && stalledMidStage ? "both" : inactive ? "inactive" : "stalled-mid-stage";
      const reasonLabel =
        reason === "both"
          ? `Inactive ${s.daysInactive}d, stalled mid-${STAGE_SHORT_LABEL[currentStage as keyof CohortStudent["stagePct"]]}`
          : reason === "inactive"
          ? `Inactive ${s.daysInactive}d`
          : `Started ${STAGE_SHORT_LABEL[currentStage as keyof CohortStudent["stagePct"]]}, no progress ${s.daysInactive}d`;

      flagged.push({
        ...s,
        cohortId: cohort.id,
        cohortName: cohort.name,
        currentStage,
        currentStagePct,
        reason,
        reasonLabel,
        riskScore: s.daysInactive,
      });
    }
  }

  return flagged.sort((a, b) => b.riskScore - a.riskScore);
}

export function isAtRisk(s: CohortStudent): boolean {
  return s.daysInactive >= 21;
}

export function isOnWatch(s: CohortStudent): boolean {
  return s.daysInactive >= 7 && s.daysInactive < 21;
}

export function isActive(s: CohortStudent): boolean {
  return s.daysInactive < 7;
}

export function cohortAvgCompletion(c: Cohort): number {
  if (c.students.length === 0) return 0;
  return Math.round(
    c.students.reduce((sum, s) => sum + studentOverallPct(s), 0) / c.students.length
  );
}

export function cohortAtRiskCount(c: Cohort): number {
  return c.students.filter(isAtRisk).length;
}

export function cohortActiveCount(c: Cohort): number {
  return c.students.filter(isActive).length;
}

export function cohortWatchCount(c: Cohort): number {
  return c.students.filter(isOnWatch).length;
}

